function openEntry(entry=null,fromDraft=false){if(entry?.cardId&&!fromDraft){const b=findBill(entry.invoiceId);if(b&&b.status!=='open'){toast('Esta fatura já está fechada. Abra Cartões para corrigir ou desfazer o pagamento.');return}}if(!state.accounts.length&&!cards().length){toast('Adicione uma conta primeiro.');openAccount();return}editing={id:entry?.id||crypto.randomUUID(),version:fromDraft?null:entry?.version,createOnly:fromDraft||!entry,fromDraft};$('editorTitle').textContent=editing.createOnly?'Confira o lançamento':'Editar lançamento';$('editorError').textContent='';$('entryKind').value=entry?.kind||'expense';$('entryAmount').value=entry?.cents?money(entry.cents):'';$('entryDescription').value=entry?.description||'';$('entryAccount').innerHTML=state.accounts.filter(a=>!a.deleted).map(a=>'<option value="'+a.id+'">'+escape(a.name)+'</option>').join('');if(entry?.accountId)$('entryAccount').value=entry.accountId;$('entryCategory').innerHTML=[...new Set([...categories,...(entry?.category?[entry.category]:[])])].map(c=>'<option>'+escape(c)+'</option>').join('');$('entryCategory').value=entry?.category||'Outros';$('entryScope').value=entry?.scope||'casal';$('entryStatus').value=entry?.status||'paid';$('entryDate').value=entry?.date||today();$('entryDue').value=entry?.dueDate||entry?.date||today();$('entryPaid').value=entry?.paidDate||entry?.date||today();$('entryPayment').disabled=!!entry?.cardId&&!fromDraft;$('entryPayment').value=entry?.cardId||entry?.credit?'credit':'cash';$('entryCard').innerHTML=cards().map(c=>'<option value="'+c.id+'">'+escape(c.name)+'</option>').join('');if(entry?.cardId)$('entryCard').value=entry.cardId;$('entryInvoiceMonth').value=entry?.invoiceId?.slice(entry.cardId.length+1)||'';if(!state.accounts.length&&cards().length)$('entryPayment').value='credit';updateCreditFields(false);$('editor').showModal()}
