async function changeEntry(id,action){if(busy)return;const e=state.entries.find(e=>e.id===id);if(!e)return;const question=action==='deleteEntry'?'Mover este lançamento para a lixeira? Ele deixará de entrar nos saldos e poderá ser restaurado.':action==='restoreEntry'?'Restaurar este lançamento? Ele voltará a entrar nos saldos.':'Confirmar '+(e.kind==='income'?'recebimento':'pagamento')+' de '+money(e.cents)+' hoje na conta '+accountName(e.accountId)+'?';if(!confirm(question))return;busy=true;try{const result=await api({action,id,version:e.version,paidDate:today()});state=result.data;if(e.cardId&&creditFlow?.id===e.invoiceId)afterCreditPurchase();render();toast('Lançamento atualizado.')}catch(err){toast(err.message);await refresh().catch(()=>{})}finally{busy=false}}
