function showVoiceState(status){if(!voiceOpen||user?.id!==voiceSession?.user||auth?.token!==voiceSession?.token)return;const listening=['starting','listening','stopping'].includes(status.phase);$('voiceText').readOnly=listening;if(listening||status.phase==='review')$('voiceText').value=[voicePrefix,status.text].filter(Boolean).join(' ');$('voiceStatus').textContent=status.phase==='starting'?'Permitindo acesso ao microfone…':status.phase==='listening'?'🎙 Ouvindo… Fale sua mensagem.':status.phase==='stopping'?'Finalizando o reconhecimento…':status.phase==='review'?'Foi isso que você falou? Confira e confirme abaixo.':status.phase==='dictation'?'Toque no microfone do teclado do iPhone, fale e confira o texto.':'Você pode ditar pelo microfone do teclado ou escrever aqui.';$('voiceError').textContent=status.error;$('voiceStop').hidden=!listening;$('voiceStop').disabled=status.phase==='stopping';$('voiceConfirm').hidden=listening;$('voiceRetry').hidden=listening||!status.supported||voiceDevice.keyboard||status.phase==='dictation';$('voiceKeyboard').hidden=status.phase==='dictation';$('voiceConfirm').disabled=!$('voiceText').value.trim()||$('voiceText').value.length>700;$('voiceDialog').classList.toggle('listening',listening);if($('voiceText').value.length>700)$('voiceError').textContent='A mensagem ficou longa. Encurte o texto para até 700 caracteres antes de confirmar.';}
function openVoice(){if(voiceOpen)return;if(chatSending||busy){toast('Aguarde a operação terminar para falar.');return;}voiceSession={user:user?.id,token:auth?.token};voicePrefix=$('chatText')?.value.trim()||'';voiceOpen=true;$('chatText')?.blur?.();$('voiceText').value=voicePrefix;$('voiceDialog').showModal();voice.start();if(['dictation','unsupported'].includes(voice.phase))focusVoiceText();}
