$('voiceKeyboard').onclick=()=>{voice.useKeyboard();focusVoiceText();};
$('voiceClose').onclick=closeVoice;$('voiceCancel').onclick=closeVoice;$('voiceStop').onclick=()=>voice.stop();$('voiceRetry').onclick=()=>voice.start();$('voiceDialog').addEventListener('cancel',closeVoice);$('voiceDialog').addEventListener('close',()=>{if(voiceOpen)closeVoice()});$('voiceText').oninput=()=>{$('voiceConfirm').disabled=!$('voiceText').value.trim()||$('voiceText').value.length>700;$('voiceError').textContent=$('voiceText').value.length>700?'Encurte a mensagem para até 700 caracteres.':'';};
$('voiceConfirm').onclick=async()=>{if(!voiceOpen||['starting','listening','stopping'].includes(voice.phase))return;if(user?.id!==voiceSession?.user||auth?.token!==voiceSession?.token){closeVoice();return;}const text=$('voiceText').value.trim();if(!text||text.length>700)return;closeVoice();await sendMessage(text);};
