const findBill=id=>invoices().find(b=>b.id===id);
const draftReady=()=>draft&&draft.kind&&draft.cents&&draft.status&&(draft.credit?draft.cardId:draft.accountId)&&!draft.invalidDate;
function dueBills(){return invoices().filter(b=>b.status!=='paid'&&(b.status==='open'||invoiceTotal(state,b.id)>0)&&(!b.remindAfter||b.remindAfter<=today())&&(b.status==='open'?b.closeDate<=today():b.dueDate<=today())).sort((a,b)=>a.dueDate.localeCompare(b.dueDate))}
function announceInvoices(){if(!user||tab!=='chat'||draft||creditFlow||dueFlow||$('editor').open||$('cardEditor').open)return;for(const b of dueBills()){const key='lt_pf_ly_reminder_'+user.id+'_'+b.id+'_'+b.status+'_'+today();if(localStorage.getItem(key))continue;localStorage.setItem(key,'1');startCredit(b.id,b.status==='closed',false);break}}
function reminderView(){const bills=dueBills();return bills.map(b=>'<div class="card reminder-card"><h3>'+escape(billName(b))+' · '+(b.status==='open'?'Vamos conferir a fatura?':'A fatura foi paga?')+'</h3><p>'+money(invoiceTotal(state,b.id))+' · '+(b.status==='open'?'Fechamento: '+formatDate(b.closeDate):'Vencimento: '+formatDate(b.dueDate))+'</p><button data-bill-flow="'+b.id+'" data-mode="'+(b.status==='closed'?'pay':'close')+'">'+(b.status==='closed'?'Informar pagamento':'Conferir fechamento')+'</button></div>').join('')}
function creditFlowView(){if(!creditFlow)return '';const b=findBill(creditFlow.id);if(!b)return '';let actions='';const stage=creditFlow.stage;
 if(stage==='closedQuestion'||stage==='payQuestion')actions='<button data-credit-answer="sim">Sim</button><button class="secondary" data-credit-answer="não">Ainda não</button>';
 if(stage==='bankTotal')actions='<label for="billBankTotal">Total da fatura no banco (R$)</label><input id="billBankTotal" inputmode="decimal" placeholder="R$ 0,00" aria-label="Total da fatura no banco"><button data-credit-check-bank>Comparar os totais</button>';
 if(stage==='confirmTotal')actions='<button data-credit-answer="sim">O total está certo</button><button class="secondary" data-credit-answer="não">O total é diferente</button>';
 if(stage==='confirmClose')actions='<button data-credit-answer="confirmar">Confirmar fechamento · '+money(creditFlow.total)+'</button>';
 if(stage==='finding')actions='<button class="secondary" data-open-bill="'+b.id+'">Conferir compras</button><button data-credit-difference>Lançar o que faltou</button>';
 if(stage==='payAccount')actions=state.accounts.filter(a=>!a.deleted).map(a=>'<button class="secondary" data-pay-account="'+a.id+'">'+escape(a.name)+'</button>').join('')||'<button data-add-account>Adicionar conta</button>';
 if(stage==='payConfirm')actions='<label for="billPaidDate">Data do pagamento</label><input id="billPaidDate" type="date" value="'+escape(creditFlow.paidDate||today())+'"><button data-credit-answer="confirmar">Confirmar pagamento · '+money(creditFlow.total)+'</button>';
 return '<div class="bubble credit-flow"><small>'+escape(billName(b))+' · Fatura '+b.cycle.split('-').reverse().join('/')+'</small>'+(stage==='finding'?'<strong class="difference-title">Divergência encontrada</strong>':'')+'<p>'+escape(creditFlow.question||'Responda na conversa.')+'</p>'+actions+'<button class="text-button" data-cancel-credit>Continuar depois</button></div>';
}
function flowSay(message){creditFlow.question=message;addMessage('bot',message);render()}
function invoiceSummary(b){const items=invoiceItems(state,b.id);return items.map(e=>formatDate(e.date)+' · '+e.description+' · '+money(e.cents)).join('\n')+'\nTotal registrado: '+money(invoiceTotal(state,b.id))+'.'}
function differenceText(b,cents){const total=invoiceTotal(state,b.id),diff=cents-total;return 'Divergência de '+money(Math.abs(diff))+'.\nBanco: '+money(cents)+'. App: '+money(total)+'.\n'+(diff>0?'Faltam '+money(diff)+' nos registros. Confira se esqueceu alguma compra ou tarifa e me diga qual foi.':'O app está '+money(-diff)+' acima do banco. Confira se alguma compra está duplicada, tem valor errado ou pertence a outra fatura.');}
function showCloseTotal(b){creditFlow.total=invoiceTotal(state,b.id);creditFlow.version=b.version;const known=b.bankCents!==null&&b.bankCents!==undefined;if(known&&b.bankCents!==creditFlow.total){creditFlow.stage='finding';creditFlow.bankCents=b.bankCents;flowSay(invoiceSummary(b)+'\n'+differenceText(b,b.bankCents));}else{creditFlow.stage='bankTotal';flowSay(invoiceSummary(b)+'\nQual valor total aparece na fatura do banco? Informe abaixo para eu comparar. Dizer que a fatura fechou ainda não confirma que os valores batem.');}}

function showPayAccount(b){creditFlow.stage='payAccount';creditFlow.total=invoiceTotal(state,b.id);creditFlow.version=b.version;flowSay('Qual conta pagou os '+money(creditFlow.total)+' da fatura '+billName(b)+'? Escolha uma conta abaixo ou escreva seu nome.')}
function choosePayAccount(id){if(!creditFlow||creditFlow.stage!=='payAccount')return;const a=state.accounts.find(a=>a.id===id&&!a.deleted);if(!a)return;creditFlow.accountId=id;creditFlow.paidDate=today();creditFlow.stage='payConfirm';flowSay('Vou registrar o pagamento de '+money(creditFlow.total)+' pela conta '+a.name+'. Confira a data e confirme abaixo. Este registro não faz uma transferência bancária.')}
function startCredit(id,pay=false,redraw=true){const b=findBill(id);if(!b)return;creditFlow={id,stage:pay&&b.status==='closed'?'payQuestion':'closedQuestion'};tab='chat';const text=creditFlow.stage==='payQuestion'?'A fatura '+billName(b)+' de '+money(invoiceTotal(state,b.id))+' venceu em '+formatDate(b.dueDate)+'. Ela foi paga?':'A fatura '+billName(b)+' tem fechamento previsto para '+formatDate(b.closeDate)+'. Ela já fechou no banco?';creditFlow.question=text;addMessage('bot',text);if(redraw)render()}
async function creditWrite(body){if(busy)throw Error('Aguarde o registro terminar.');busy=true;try{const r=await api(body);state=r.data;connection('Compartilhado entre Luciano e Yasmin · Atualizado');return r}catch(e){await refresh(false).catch(()=>{});throw e}finally{busy=false}}
async function handleCreditReply(text){if(!creditFlow||draft)return false;const n=normalize(text),b=findBill(creditFlow.id);if(!b){creditFlow=null;return false}
 const yes=/^(sim|s|isso|certo|esta certo|ta certo|fechou|foi paga|paguei|ja paguei|confirmar|confirmo|confirmar fechamento|confirmar pagamento)[.!]*$/.test(n),no=/^(nao|n|ainda nao|nao fechou|nao paguei|nao foi paga)[.!]*$/.test(n);
 if(/^(cancelar|cancela|depois)$/.test(n)){creditFlow=null;addMessage('bot','Tudo bem. Você pode retomar em Cartões. Nenhum fechamento ou pagamento foi confirmado.');render();return true}
 if(/\b(gastei|comprei|recebi|ganhei)\b/.test(n)&&creditFlow.stage!=='finding'){creditFlow=null;return false}
 try{
  if(no&&['closedQuestion','payQuestion'].includes(creditFlow.stage)){await creditWrite({action:'invoiceSnooze',id:b.id,version:b.version,remindAfter:shiftDate(today(),1)});creditFlow=null;addMessage('bot','A fatura continua pendente. Amanhã, ao abrir a conversa, lembro novamente.');render();return true}
  if(creditFlow.stage==='closedQuestion'){if(yes)showCloseTotal(b);else flowSay('Ela já fechou no banco? Responda sim ou ainda não.');return true}
  if(creditFlow.stage==='payQuestion'){if(yes)showPayAccount(b);else flowSay('Ela foi paga? Responda sim ou ainda não.');return true}
  if(creditFlow.stage==='confirmTotal'&&yes){await creditWrite({action:'invoiceCheck',id:b.id,version:b.version,bankCents:creditFlow.total});const current=findBill(b.id);creditFlow.stage='confirmClose';creditFlow.version=current.version;flowSay('Total conferido: '+money(creditFlow.total)+'. Confirme abaixo para fechar a fatura.');return true}
  if(creditFlow.stage==='confirmTotal'&&no){creditFlow.stage='bankTotal';flowSay('Qual é o total que aparece na fatura do banco? Ex.: 350,00');return true}
  if(['confirmTotal','bankTotal'].includes(creditFlow.stage)){const parsed=moneyCents(text),match=text.match(/(?:R\$\s*)?(\d[\d.,]*)/i),cents=parsed??(match?moneyCents(match[1]):null);if(cents===null||cents<0){creditFlow.stage='bankTotal';flowSay('Informe o total do banco em reais. Ex.: 350,00');return true}await creditWrite({action:'invoiceCheck',id:b.id,version:b.version,bankCents:cents});const current=findBill(b.id),diff=cents-invoiceTotal(state,b.id);creditFlow.bankCents=cents;if(diff===0){creditFlow.stage='confirmClose';creditFlow.total=cents;creditFlow.version=current.version;flowSay('Os totais batem: '+money(cents)+'. Confirme abaixo para fechar.')}else{creditFlow.stage='finding';flowSay(differenceText(current,cents))}return true}
  if(creditFlow.stage==='confirmClose'){if(!yes){flowSay('Para fechar com o total conferido, toque em “Confirmar fechamento”.');return true}await creditWrite({action:'invoiceClose',id:b.id,version:creditFlow.version,confirmedCents:creditFlow.total});creditFlow=null;addMessage('bot','Fatura '+billName(b)+' fechada e conferida. Total: '+money(invoiceTotal(state,b.id))+'. Vencimento: '+formatDate(b.dueDate)+'. O saldo das contas continua igual; só muda quando você confirmar o pagamento.');render();return true}
  if(creditFlow.stage==='payAccount'){const match=state.accounts.filter(a=>!a.deleted&&(normalize(a.name)===n||n.includes(normalize(a.name))));if(match.length===1)choosePayAccount(match[0].id);else flowSay('Escolha a conta que pagou a fatura nos botões abaixo.');return true}
  if(creditFlow.stage==='payConfirm'){if(!yes){flowSay('Confira a conta, a data e toque em “Confirmar pagamento”.');return true}const paidDate=$('billPaidDate')?.value||creditFlow.paidDate;await creditWrite({action:'invoicePay',id:b.id,version:creditFlow.version,confirmedCents:creditFlow.total,accountId:creditFlow.accountId,paidDate});const account=accountName(creditFlow.accountId);creditFlow=null;addMessage('bot','Pagamento da fatura '+billName(b)+' registrado: '+money(invoiceTotal(state,b.id))+' na conta '+account+'. As compras foram baixadas juntas, sem duplicar a despesa.');render();return true}
  if(creditFlow.stage==='finding'){if(no||yes){flowSay('Me diga a compra que faltou e seu valor. Ex.: “Faltou 30,00 de recarga do celular”. Se houver duplicação ou erro, use “Conferir compras”.');return true}const p=parseMessage(text,[],today(),cards()),m=text.match(/(?:R\$\s*)?(\d[\d.,]*)/i);draft={id:crypto.randomUUID(),description:text.slice(0,300),kind:'expense',credit:true,cardId:b.cardId,invoiceId:b.id,cents:p.cents||(m?moneyCents(m[1]):null),status:'pending',scope:p.scope||'casal',category:p.category,date:p.date||today(),dueDate:b.dueDate};addMessage('bot',draftReady()?'Confira a compra que faltou antes de salvar.':missingPrompt());render();return true}
 }catch(e){toast(e.message);if(creditFlow&&e.status===409){creditFlow.stage='confirmTotal';showCloseTotal(findBill(b.id)||b)}else{addMessage('bot',e.message);render()}return true}return false;
}
function afterCreditPurchase(){if(!creditFlow||creditFlow.stage!=='finding')return;const b=findBill(creditFlow.id);if(!b)return;if(b.bankCents===null||b.bankCents===undefined){showCloseTotal(b);return}const total=invoiceTotal(state,b.id),diff=b.bankCents-total;if(diff===0){creditFlow.stage='confirmClose';creditFlow.total=total;creditFlow.version=b.version;addMessage('bot','Agora os totais batem: '+money(total)+'. Confirme o fechamento abaixo.');creditFlow.question='Agora os totais batem: '+money(total)+'. Confirme o fechamento abaixo.'}else{const text='Registros atualizados. Banco: '+money(b.bankCents)+'. App: '+money(total)+'. '+(diff>0?'Ainda faltam '+money(diff)+'.':'O app está '+money(-diff)+' acima do banco.')+' Confira as outras compras.';creditFlow.question=text;addMessage('bot',text)}}
function cardsView(){let selected=creditSelectedBill&&findBill(creditSelectedBill);const body=selected?invoiceView(selected):invoices().filter(b=>b.status!=='paid').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).map(b=>invoiceCard(b)).join('');return '<div class="invoice-view"><div class="page-head"><div><h2>Cartões e faturas</h2><p class="muted">Compra no crédito só desconta da conta quando a fatura é paga.</p></div><button data-add-card>+ Cartão</button></div>'+(!cards().length?'<div class="card empty"><h3>Cadastre seu primeiro cartão</h3><p class="muted">Nome, fechamento e vencimento. Depois, registre as compras pela conversa.</p><button data-add-card>Adicionar cartão</button></div>':cards().map(c=>'<div class="card card-mini"><div><h3>'+escape(c.name)+'</h3><span class="muted">Fecha dia '+c.closingDay+' · Vence dia '+c.dueDay+'</span>'+cardLimitView(c)+'</div><button class="text-button" data-edit-card="'+c.id+'">Editar</button></div>').join('')+(selected?'<button class="secondary" data-all-bills>Ver todas as faturas</button>':'')+body+'<div class="card invoice-history"><details><summary>Faturas pagas</summary>'+invoices().filter(b=>b.status==='paid').sort((a,b)=>b.dueDate.localeCompare(a.dueDate)).map(b=>invoiceCard(b)).join('')+'</details></div>')+'<p class="muted">As perguntas de fechamento e vencimento aparecem na conversa ao abrir o app nas datas previstas. Elas continuam disponíveis enquanto a fatura estiver pendente.</p></div>'}
let creditSelectedBill=null;
function invoiceCard(b){const total=invoiceTotal(state,b.id),diff=b.bankCents===null||b.bankCents===undefined?null:b.bankCents-total;return '<div class="card"><div class="bill-top"><div><h3>'+escape(billName(b))+'</h3><span class="muted">Fatura · fechamento '+b.cycle.split('-').reverse().join('/')+'</span></div><span class="badge '+(b.status==='paid'?'':'pending')+'">'+({open:'Aberta',closed:'Fechada · a pagar',paid:'Paga'}[b.status])+'</span></div><div class="bill-dates"><span>Fecha: '+formatDate(b.closeDate)+'</span><span>Vence: '+formatDate(b.dueDate)+'</span></div><div class="invoice-total">'+money(total)+'</div>'+(diff?'<div class="difference">'+(diff>0?'Faltam '+money(diff)+' para bater com o banco.':'O app está '+money(-diff)+' acima do banco.')+'</div>':'')+(b.status==='paid'?'<p class="muted">'+(invoiceTotal(state,b.id)===0?'Sem valor a pagar':'Paga em '+formatDate(b.paidDate)+' · '+escape(accountName(b.accountId)))+'</p>':'')+'<div class="row-actions"><button class="secondary" data-open-bill="'+b.id+'">Ver compras</button>'+(b.status==='open'?'<button data-bill-flow="'+b.id+'" data-mode="close">Conferir e fechar</button>':b.status==='closed'?'<button data-bill-flow="'+b.id+'" data-mode="pay">Registrar pagamento</button>':'')+'</div></div>'}
function invoiceView(b){const list=invoiceItems(state,b.id);return invoiceCard(b)+'<div class="card"><h3>Compras desta fatura</h3><div class="bill-items">'+(list.length?list.map(e=>'<div class="bill-item"><div><strong>'+escape(e.description)+'</strong><small>'+formatDate(e.date)+' · '+escape(e.category)+' · '+escape(e.createdBy)+'</small></div><strong>'+money(e.cents)+'</strong>'+(b.status==='open'?'<button class="text-button" data-edit="'+e.id+'">Editar</button><button class="text-button danger" data-delete="'+e.id+'">Apagar</button>':'')+'</div>').join(''):'<p class="muted">Nenhuma compra nesta fatura.</p>')+'</div>'+ (b.status==='open'?'<button data-bill-purchase="'+b.id+'">+ Compra nesta fatura</button>':b.status==='closed'?'<button class="secondary" data-reopen-bill="'+b.id+'">Reabrir para corrigir compras</button>':'<button class="secondary" data-undo-bill="'+b.id+'">Desfazer registro de pagamento</button>')+'</div>'}
function cardLimitView(card){const v=cardLimit(state,card);return '<div class="card-limit">'+(v.limit===null?'<span class="muted">Limite não informado</span>':'<span>Limite: <b>'+money(v.limit)+'</b></span><span>Utilizado: <b>'+money(v.used)+'</b></span><span class="'+(v.available<0?'red':'green')+'">Disponível: <b>'+money(v.available)+'</b></span><small>Considera as compras registradas ainda não pagas.</small>')+'</div>';}
function openCard(card=null){cardEditing=card||{id:crypto.randomUUID()};$('cardTitle').textContent=card?'Editar cartão':'Adicionar cartão';$('cardName').value=card?.name||'';$('cardClosing').value=card?.closingDay||'';$('cardDue').value=card?.dueDay||'';$('cardLimit').value=card?.limitCents===undefined||card?.limitCents===null?'':money(card.limitCents);$('cardError').textContent='';$('cardEditor').showModal()}
function billPurchase(id){const b=findBill(id);if(!b||b.status!=='open')return;openEntry({id:crypto.randomUUID(),kind:'expense',credit:true,cardId:b.cardId,invoiceId:b.id,date:today(),dueDate:b.dueDate,status:'pending',scope:'casal'},true)}
function setCreditDate(){if($('entryPayment').value!=='credit')return;const card=cards().find(c=>c.id===$('entryCard').value);if(!card)return;const date=$('entryDate').value||today();$('entryInvoiceMonth').value=purchaseCycle(date,card,invoices());updateCreditFields(false)}
function updateCreditFields(auto=true){const isCredit=$('entryPayment').value==='credit';$('creditFields').hidden=!isCredit;$('creditEntryHint').hidden=!isCredit;$('entryCard').disabled=!isCredit;$('entryCard').required=isCredit;$('entryInvoiceMonth').disabled=!isCredit;$('entryInvoiceMonth').required=isCredit;$('entryAccount').disabled=isCredit;$('entryAccount').required=!isCredit;$('entryStatus').disabled=isCredit;$('entryKind').disabled=isCredit;$('entryDue').disabled=isCredit;if(isCredit){$('entryKind').value='expense';$('entryStatus').value='pending';const card=cards().find(c=>c.id===$('entryCard').value);if(card){if(auto||!$('entryInvoiceMonth').value)$('entryInvoiceMonth').value=purchaseCycle($('entryDate').value||today(),card,invoices());const id=invoiceId(card.id,$('entryInvoiceMonth').value),bill=findBill(id),dates=bill||invoiceDates(card,$('entryInvoiceMonth').value);$('entryDue').value=dates.dueDate;$('creditEntryHint').textContent='Vai para a fatura '+$('entryInvoiceMonth').value.split('-').reverse().join('/')+' do '+card.name+'. Vence em '+formatDate(dates.dueDate)+'. Só desconta da conta quando a fatura é paga.'+(bill&&bill.status!=='open'?' Esta fatura já está fechada; reabra antes de alterar suas compras.':'');}else $('creditEntryHint').textContent='Cadastre seu cartão na aba Cartões antes de registrar esta compra.';}updatePaidField()}
function bindCreditView(){if($('billBankTotal')){const input=$('billBankTotal');input.value=creditFlow?.bankInput||'';bindMoneyInput(input);input.addEventListener('input',()=>{if(creditFlow)creditFlow.bankInput=input.value;});}document.querySelectorAll('[data-credit-check-bank]').forEach(b=>b.onclick=()=>{const text=$('billBankTotal').value;if(!text.trim()){toast('Informe o total da fatura no banco.');return}sendMessage(text);});if($('billPaidDate'))$('billPaidDate').onchange=e=>{if(creditFlow)creditFlow.paidDate=e.target.value;};document.querySelectorAll('[data-add-card]').forEach(b=>b.onclick=()=>openCard());document.querySelectorAll('[data-edit-card]').forEach(b=>b.onclick=()=>openCard(cards().find(c=>c.id===b.dataset.editCard)));document.querySelectorAll('[data-bill-flow]').forEach(b=>b.onclick=()=>startCredit(b.dataset.billFlow,b.dataset.mode==='pay'));document.querySelectorAll('[data-open-bill]').forEach(b=>b.onclick=()=>{creditSelectedBill=b.dataset.openBill;go('cards')});document.querySelectorAll('[data-all-bills]').forEach(b=>b.onclick=()=>{creditSelectedBill=null;render()});document.querySelectorAll('[data-bill-purchase]').forEach(b=>b.onclick=()=>billPurchase(b.dataset.billPurchase));document.querySelectorAll('[data-credit-answer]').forEach(b=>b.onclick=()=>{sendMessage(b.dataset.creditAnswer)});document.querySelectorAll('[data-pay-account]').forEach(b=>b.onclick=()=>{addMessage('me',accountName(b.dataset.payAccount));choosePayAccount(b.dataset.payAccount)});document.querySelectorAll('[data-cancel-credit]').forEach(b=>b.onclick=()=>{creditFlow=null;render()});document.querySelectorAll('[data-credit-difference]').forEach(b=>b.onclick=()=>{$('chatText').value='Faltou 30,00 de recarga do celular';$('chatText').focus();$('chatText').select()});for(const [attr,action]of [['reopenBill','invoiceReopen'],['undoBill','invoiceUndoPay']]){const css=attr==='reopenBill'?'reopen-bill':'undo-bill';document.querySelectorAll('[data-'+css+']').forEach(button=>button.onclick=async()=>{const b=findBill(button.dataset[attr]);if(!b||busy)return;if(!confirm(action==='invoiceReopen'?'Reabrir esta fatura para corrigir as compras?':'Desfazer o registro de pagamento? O valor volta ao saldo da conta e a fatura volta a ficar pendente. Isso não desfaz um pagamento no banco.'))return;try{await creditWrite({action,id:b.id,version:b.version});render();toast('Fatura atualizada.')}catch(e){toast(e.message)}})}}
$('cardForm').onsubmit=async event=>{event.preventDefault();if(busy)return;$('saveCard').disabled=true;$('cardError').textContent='';try{const limit=$('cardLimit').value.trim()?moneyCents($('cardLimit').value):null;if($('cardLimit').value.trim()&&(limit===null||limit<0))throw Error('Informe um limite válido em reais.');await creditWrite({action:'card',id:cardEditing.id,version:cardEditing.version,name:$('cardName').value,closingDay:Number($('cardClosing').value),dueDay:Number($('cardDue').value),limitCents:limit});$('cardEditor').close();if(draft?.credit&&!draft.cardId&&cards().length===1){draft.cardId=cards()[0].id;draft.invoiceId=invoiceId(draft.cardId,purchaseCycle(draft.date,cards()[0],invoices()));addMessage('bot','Cartão cadastrado. Agora confira a compra para salvar na fatura.');}render();toast('Cartão salvo.')}catch(e){$('cardError').textContent=e.message}finally{$('saveCard').disabled=false}};
$('closeCard').onclick=()=>{if(!busy)$('cardEditor').close()};$('cardEditor').addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('entryPayment').onchange=()=>updateCreditFields(true);$('entryCard').onchange=setCreditDate;$('entryDate').onchange=()=>{if($('entryPayment').value==='credit')setCreditDate()};$('entryInvoiceMonth').onchange=()=>{if($('entryInvoiceMonth').value)updateCreditFields(false)};

bindMoneyInput($('cardLimit'));window.visualViewport?.addEventListener('resize',()=>{if(tab==='chat'&&document.activeElement===$('chatText'))scheduleChatScroll()});

function announceBudgetAlerts(){if(!state.budgetSettings?.enabled||tab!=='chat')return;for(const event of state.budgetAlerts||[]){if(event.response||announcedBudgets.has(event.id))continue;announcedBudgets.add(event.id);addMessage('bot','⚠ '+event.category+': passou do orçamento planejado em '+money(event.excessCents)+'. Planejado: '+money(event.limitCents)+'. Gasto: '+money(event.spentCents)+'. Você pode registrar o motivo em Orçamentos, ou escolher não justificar. O aviso ficará no histórico.');}}
function budgetNotice(){const pending=(state.budgetAlerts||[]).filter(e=>!e.response);return state.budgetSettings?.enabled&&pending.length?'<div class="card"><h3>⚠ Orçamento ultrapassado</h3><p class="muted">'+pending.length+' aviso(s) no histórico. Registrar um motivo é opcional.</p><button data-budget-open class="secondary">Ver avisos e justificar</button></div>':'';}
function budgetView(){const enabled=!!state.budgetSettings?.enabled,list=(state.budgets||[]).filter(b=>b.month===month&&!b.deleted);return '<div class="page-head"><div><h2>Orçamentos</h2><p class="muted">Limites mensais opcionais para o casal</p></div><button data-budget-back class="secondary">Voltar à conversa</button></div><div class="card"><h3>Planejar seus gastos</h3><p class="muted">'+(enabled?'Ativado. Os avisos aparecem na conversa e ficam no histórico.':'Desativado. Ative quando quiser definir metas de gastos.')+'</p><button id="budgetToggle" class="'+(enabled?'secondary':'')+'">'+(enabled?'Desativar orçamentos':'Ativar orçamentos')+'</button><p class="muted" style="margin-top:12px">Desativar preserva os limites e justificativas já salvos.</p></div><div class="filters"><input id="budgetMonth" type="month" value="'+month+'" aria-label="Mês do orçamento"></div>'+(enabled?'<form id="budgetForm" class="card"><h3>Adicionar limite do mês</h3><label for="budgetCategory">Categoria</label><select id="budgetCategory">'+budgetCategories.map(c=>'<option>'+escape(c)+'</option>').join('')+'</select><label for="budgetAmount">Quanto pode gastar no mês?</label><input id="budgetAmount" inputmode="decimal" placeholder="R$ 0,00" required><button type="submit" style="margin-top:15px">Salvar limite mensal</button></form>':'')+list.map(b=>{const spent=budgetSpent(state,b),left=b.limitCents-spent;return '<div class="card"><h3>'+escape(b.category)+'</h3><p>Planejado: <b>'+money(b.limitCents)+'</b><br>Gasto: <b>'+money(spent)+'</b><br><strong class="'+(left<0?'red':'green')+'">'+(left<0?'Ultrapassou em '+money(-left):'Ainda pode gastar '+money(left))+'</strong></p>'+(enabled?'<label>Novo limite mensal</label><input data-budget-limit="'+b.id+'" value="'+money(b.limitCents)+'" inputmode="decimal"><button data-budget-save="'+b.id+'" class="secondary" style="margin-top:12px">Atualizar limite</button>':'')+'</div>'}).join('')+'<p class="muted">Limites são definidos para o mês selecionado. Combustível usa a descrição (gasolina, diesel, etanol, abastecimento ou posto). As outras metas usam a categoria do lançamento. Cartão entra pela data da compra; outras despesas, quando pagas. Uma mesma compra não é somada novamente ao pagar a fatura.</p><h3>Histórico de excessos · '+month.split('-').reverse().join('/')+'</h3>'+((state.budgetAlerts||[]).filter(e=>e.month===month).slice().reverse().map(e=>'<div class="card"><h3>'+escape(e.category)+' · '+money(e.excessCents)+' acima do limite</h3><p class="muted">'+formatDate(e.createdAt.slice(0,10))+' · '+escape(e.createdBy)+'<br>Limite na ocasião: '+money(e.limitCents)+' · Gasto: '+money(e.spentCents)+'</p>'+(e.response?'<p>'+escape(e.response==='skip'?'Escolheu não justificar.':e.note)+'</p><p class="muted">'+escape(e.respondedBy)+' · '+formatDate(e.respondedAt.slice(0,10))+'</p>':'<p class="muted">Justificativa opcional. Você pode decidir depois.</p><textarea data-budget-note="'+e.id+'" maxlength="700" placeholder="Ex.: viagem extra ou aumento do combustível" aria-label="Motivo do excesso"></textarea><div class="row-actions"><button data-budget-reason="'+e.id+'">Salvar motivo</button><button data-budget-skip="'+e.id+'" class="secondary">Não quero justificar</button></div>')+'</div>').join('')||'<div class="card"><p class="muted">Nenhum excesso registrado neste mês.</p></div>');}
async function budgetWrite(body){if(busy)return;busy=true;try{const result=await api(body);state=result.data;render();toast('Orçamento salvo para vocês.')}catch(e){toast(e.message);if(e.status===409)await refresh().catch(()=>{})}finally{busy=false}}
function bindBudgetView(){document.querySelectorAll('[data-budget-open]').forEach(b=>b.onclick=()=>{month=today().slice(0,7);go('budgets')});document.querySelectorAll('[data-budget-back]').forEach(b=>b.onclick=()=>go('chat'));if($('budgetToggle'))$('budgetToggle').onclick=()=>budgetWrite({action:'budgetSettings',enabled:!state.budgetSettings?.enabled,version:state.budgetSettings?.version||0});if($('budgetMonth'))$('budgetMonth').onchange=e=>{if(e.target.value){month=e.target.value;render()}};if($('budgetForm')){bindMoneyInput($('budgetAmount'));$('budgetForm').onsubmit=e=>{e.preventDefault();budgetWrite({action:'budget',id:crypto.randomUUID(),month,category:$('budgetCategory').value,limitCents:moneyCents($('budgetAmount').value)})}};document.querySelectorAll('[data-budget-limit]').forEach(bindMoneyInput);document.querySelectorAll('[data-budget-save]').forEach(button=>button.onclick=()=>{const b=state.budgets.find(b=>b.id===button.dataset.budgetSave);const input=document.querySelector('[data-budget-limit="'+b.id+'"]');budgetWrite({action:'budget',id:b.id,month:b.month,category:b.category,limitCents:moneyCents(input.value),version:b.version})});for(const [attr,response]of[['reason','note'],['skip','skip']])document.querySelectorAll('[data-budget-'+attr+']').forEach(button=>button.onclick=()=>{const e=state.budgetAlerts.find(e=>e.id===button.dataset[attr==='reason'?'budgetReason':'budgetSkip']);budgetWrite({action:'budgetResponse',id:e.id,version:e.version,response,note:response==='note'?document.querySelector('[data-budget-note="'+e.id+'"]').value:''})});}

function announceEntryReminders(){if(!user||tab!=='chat'||voiceOpen||draft||creditFlow||dueFlow||chatSending||$('editor').open)return false;for(const e of duePendingEntries(state,today())){const key=entryReminderKey(user.id,e,today());if(localStorage.getItem(key)||announcedEntries.has(key))continue;announcedEntries.add(key);try{localStorage.setItem(key,'1')}catch{}startDueReminder(e.id,false);return true;}return false;}
function startDueReminder(id,redraw=true){if(draft||creditFlow){if(redraw)toast('Finalize ou cancele o lançamento ou a fatura em andamento primeiro.');return;}const e=state.entries.find(e=>e.id===id&&!e.deleted&&e.status==='pending'&&!e.cardId);if(!e)return;dueFlow={id,stage:'question'};tab='chat';addMessage('bot','🔔 Lembrete: '+e.description+' · '+money(e.cents)+', '+(e.dueDate<today()?'venceu':'vence')+' em '+formatDate(e.dueDate)+' na conta '+accountName(e.accountId)+'. '+(e.kind==='income'?'Já recebeu?':'Já pagou?')+' Pode responder “sim, hoje”, “sim, ontem” ou “ainda não”. Nenhuma baixa é feita sem confirmar.');if(redraw)render();}
function dueReminderCards(){return duePendingEntries(state,today()).map(e=>'<div class="card reminder-card"><h3>🔔 '+(e.kind==='income'?'A receber':'A pagar')+' · '+escape(e.description)+'</h3><p>'+money(e.cents)+' · '+formatDate(e.dueDate)+' · '+escape(accountName(e.accountId))+'</p><button data-due-entry="'+e.id+'" class="secondary">'+(e.kind==='income'?'Informar recebimento':'Informar pagamento')+'</button></div>').join('');}
function dueFlowView(){if(!dueFlow||dueFlow.stage!=='confirm')return '';const e=state.entries.find(e=>e.id===dueFlow.id);if(!e||e.deleted||e.status!=='pending'){dueFlow=null;return '';}return '<div class="bubble"><small>Conferir baixa</small><b>'+escape(e.description)+' · '+money(e.cents)+'</b><p>'+escape(accountName(e.accountId))+' · '+formatDate(dueFlow.paidDate)+'</p><button data-due-confirm>Confirmar '+(e.kind==='income'?'recebimento':'pagamento')+'</button><button data-due-later class="secondary">Deixar pendente</button></div>';}
async function handleDueReply(text){if(!dueFlow||draft)return false;const n=normalize(text),e=state.entries.find(e=>e.id===dueFlow.id);if(!e||e.deleted||e.status!=='pending'){dueFlow=null;addMessage('bot','Este lançamento já foi atualizado. Confira a situação em Lançamentos.');render();return true;}
 if(/^(nao|ainda nao)\b/.test(n)||/^(depois|cancelar|cancela|deixar pendente)[.!?]*$/.test(n)){dueFlow=null;addMessage('bot','Tudo bem. Continua pendente e o lembrete ficará disponível na conversa.');render();return true;}
 if(dueFlow.stage==='confirm'&&/^(confirmar|confirmo|confirmar pagamento|confirmar recebimento)[.!?]*$/.test(n)){if(busy){toast('Aguarde o registro terminar.');return true;}busy=true;try{const r=await api({action:'settleEntry',id:e.id,version:e.version,paidDate:dueFlow.paidDate});state=r.data;dueFlow=null;addMessage('bot',(e.kind==='income'?'Recebimento':'Pagamento')+' de '+money(e.cents)+' confirmado na conta '+accountName(e.accountId)+'. O lembrete desta conta foi encerrado.');render();}catch(err){addMessage('bot',err.message);if(err.status===409)await refresh(false).catch(()=>{});render();}finally{busy=false;}return true;}
 if(/^(sim|ja|paguei|ja paguei|recebi|ja recebi|foi pago|foi paga|esta pago|esta paga|foi recebido|ja foi pago|ja foi recebido)\b/.test(n)){const parsed=parseMessage(text,[],today());if(parsed.invalidDate){addMessage('bot','Qual foi a data correta do pagamento ou recebimento? Ex.: “sim, dia 07/10/2026”.');render();return true;}dueFlow={id:e.id,stage:'confirm',paidDate:parsed.date||today()};addMessage('bot','Confira '+money(e.cents)+' de '+e.description+' na conta '+accountName(e.accountId)+' em '+formatDate(dueFlow.paidDate)+'. Toque em confirmar abaixo para dar baixa.');render();return true;}return false;
}
function bindDueReminders(){document.querySelectorAll('[data-due-entry]').forEach(b=>b.onclick=()=>startDueReminder(b.dataset.dueEntry));document.querySelectorAll('[data-due-confirm]').forEach(b=>b.onclick=()=>sendMessage('confirmar'));document.querySelectorAll('[data-due-later]').forEach(b=>b.onclick=()=>sendMessage('deixar pendente'));}
